<script setup lang="ts">import {ref} from 'vue';import type {Workspace} from '../stores/workspace';import {create} from '../api/policies';import {useAction} from '../hooks/useAction';import Heading from '../components/common/Heading.vue';import Notice from '../components/common/Notice.vue';import PolicyStrip from '../components/PolicyStrip.vue';defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const name=ref('精确去重·新边界口径'),mode=ref('exact'),tie=ref(1e-12);const{busy,error,notice,act}=useAction();</script><template><Heading index="03 / BOUNDARY POLICY" title="重复点怎么处理，同面积怎么选。" detail="只做精确坐标去重或拒绝重复，不进行吸附、抽稀和坐标修补。面积容差和算法版本随快照锁定。"/><div class="method-notes"><article><span>ANDREW</span><h2>单调链凸包</h2><p>排序后以叉积转向检查构造边界。共线内点不作伪顶点；面积平移原点后计算。填平凹口不等于真实覆盖。</p></article><article><span>O(h²)</span><h2>逐凸包边方向枚举</h2><p>每方向投影全部h个凸包点，取包围框。不是线性旋转卡尺；同面积容差内选最小[0,90)方向，再按角点字典序。</p></article></div><article v-for="p in data.policies" :key="p.id" class="policy-record"><h3>{{p.name}}</h3><PolicyStrip :policy="p"/></article><section v-if="canWrite" class="form-section"><h2>保存新的不可变口径</h2><form class="form-grid" @submit.prevent="act(async()=>{await create({name,deduplication:mode,area_tie_relative:tie,algorithm_version:'andrews-edge-enumeration-v1'});await refresh()},'包络口径已保存，请在新研究中应用')"><label>口径名称<input aria-label="口径名称" required v-model="name"/></label><label>重复坐标规则<select aria-label="重复坐标规则" v-model="mode"><option value="exact">精确坐标去重并计数</option><option value="reject">拒绝任何重复坐标</option></select></label><label>同面积相对容差<input aria-label="同面积相对容差" type="number" min="0" max="0.00000001" step="any" v-model.number="tie"/></label><button class="primary" :disabled="busy">保存边界口径</button></form><Notice :error="error" :notice="notice"/></section><p class="footnote">同面积判断阈值为tie_relative×max(1,最小候选面积)。输入/结果科学值以JSON数字保存，显示位数不改变源坐标。</p></template>